for(let i=0;i<90;i++){const x=(rand()-.5)*510,z=(rand()-.6)*500;if(Math.hypot(x,z)<18)continue;const r=1+rand()*4;const m=mesh(new THREE.DodecahedronGeometry(r,0),i%3?palette.rock:palette.stone,scene,x,height(x,z)+r*.4,z);m.scale.set(1,1+rand()*2,.8);m.rotation.y=rand()*6;obstacle(x,z,r);}
