function toggleRide(){if(state!=='play')return;mounted=!mounted;ride.visible=mounted;$('rideBtn').textContent=mounted?'E · 离开座驾':'E · 召唤座驾';tone(mounted?190:330);}
$('startBtn').onclick=reset;$('restartBtn').onclick=reset;$('againBtn').onclick=reset;$('pauseBtn').onclick=pause;$('resumeBtn').onclick=()=>{state='play';show('pauseScr',false);};$('continueBtn').onclick=()=>{state='play';show('endScr',false);};$('rideBtn').onclick=toggleRide;$('muteBtn').onclick=()=>{muted=!muted;$('muteBtn').textContent=muted?'静音':'音效';$('muteBtn').setAttribute('aria-pressed',String(muted));};
window.addEventListener('keydown',e=>{if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='Escape'){if(state==='pause')$('resumeBtn').click();else pause();}if(e.code==='KeyE'&&!e.repeat)toggleRide();if(state==='play')keys.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
const stickEl=$('stick');function moveStick(e){const r=stickEl.getBoundingClientRect();let x=(e.clientX-r.left)*114/r.width-57,y=(e.clientY-r.top)*114/r.height-57;const k=Math.max(1,Math.hypot(x,y)/36);x/=k;y/=k;stick.x=x/36;stick.y=y/36;$('nub').style.transform=`translate(${x}px,${y}px)`;}
